import React from 'react'
import "../style.css"

const Add = () => {
    const [member,setMember] = useState({
    name:"",
        membership:"",
        age:""
    })

    const handleChange = (e) => {
        setMember((prev) => ({ ...prev, [e.target.name]: e.target.value }))
    }

    return (
        <div className="form">
            <h1>Add New Member</h1>
            <input type="text" onChange={handleChange} placeholder="name" name="name" />
            <input type="text" onChange={handleChange} placeholder="membership" name="membership" />
            <input type="text" onChange={handleChange} placeholder="age" name="age" />
        </div>
    )
}

export default Add
